<script setup>
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { useDownloadStore } from '@/stores/download'

const emit = defineEmits(['change'])
defineProps({
  active: String
})

// 侧边栏是常驻组件，直接读下载 store：任务一进队列，Mod下载 上的角标就会自己出现
const downloadStore = useDownloadStore()

const downloadBadge = computed(
  () => downloadStore.tasks.filter((task) => ['downloading', 'paused'].includes(task.status)).length
)

// 只有真正在跑的任务才让图标跳动；暂停时保留角标但不晃
const downloadActive = computed(
  () => downloadStore.tasks.filter((task) => task.status === 'downloading').length
)

const bump = ref(false)
let bumpTimer = null

watch(downloadBadge, (next, prev) => {
  if (next <= prev) return

  // 先卸掉再挂上，保证连续两次新增都能重新触发一次弹跳
  bump.value = false
  requestAnimationFrame(() => {
    bump.value = true
  })

  clearTimeout(bumpTimer)
  bumpTimer = setTimeout(() => {
    bump.value = false
  }, 720)
})

onBeforeUnmount(() => clearTimeout(bumpTimer))

const handleClick = (key) => {
  emit('change', key)
}
</script>

