  background: var(--danger);
  color: #fff;
  font-size: 8px;
  font-weight: 700;
  line-height: 14px;
  text-align: center;
  animation: badge-pop 0.34s cubic-bezier(0.2, 1.5, 0.4, 1);
}

.nav-badge-enter-active,
.nav-badge-leave-active {
  transition:
    opacity 0.18s ease,
    transform 0.18s ease;
}

.nav-badge-enter-from,
.nav-badge-leave-to {
